using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer uses DateTime.UtcNow
        // (non-deterministic seed data causes spurious migrations).
        // Use a fixed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Vehicle> Vehicles => Set<Vehicle>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "VehicleDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BREAKING CHANGE 1: EF Core 9 Cosmos provider now uses "$type" instead
        // of "Discriminator" by default. For existing documents that already store
        // "Discriminator", you must explicitly configure the property name to
        // maintain backward compatibility.
        modelBuilder.Entity<Vehicle>()
            .HasDiscriminator<string>("Discriminator");

        modelBuilder.Entity<Vehicle>()
            .ToContainer("Vehicles")
            .HasPartitionKey(v => v.PartitionKey);
    }
}

abstract class Vehicle
{
    public string Id { get; set; } = null!;
    public string PartitionKey { get; set; } = null!;
}
class Car : Vehicle { public int Seats { get; set; } }
class Truck : Vehicle { public double PayloadTons { get; set; } }

// BREAKING CHANGE 2: Synchronous I/O on Cosmos DB is no longer supported in
// EF Core 9. All queries/saves must use async methods.
class CosmosQueryService
{
    // BEFORE (EF Core 8 — sync was allowed):
    // var cars = db.Vehicles.OfType<Car>().ToList();
    // db.SaveChanges();

    // AFTER (EF Core 9 — must use async):
    public async Task<List<Car>> GetCarsAsync(CosmosDbContext db)
    {
        return await db.Vehicles.OfType<Car>().ToListAsync();
    }

    public async Task SaveAsync(CosmosDbContext db)
    {
        await db.SaveChangesAsync();
    }
}

