using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // BREAKING CHANGE 3: In EF Core 9, Migrate() can no longer be called inside
    // a manual transaction. Migrate() now manages its own transactions internally.
    // Wrapping it in BeginTransaction() throws InvalidOperationException.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            // Removed: using var transaction = db.Database.BeginTransaction();
            db.Database.Migrate();
            // Removed: transaction.Commit();
        });
    }
}

